import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,P as n,q as r}from"./D3cAVrQp.js";var o=i("<h1>Global Governance Biodiversity Implementation Framework v1.1.1</h1> <h2>Indigenous-Led Stewardship, Ecosystem-Rights Implementation, Regenerative Biosphere, and Constitutionally Bounded Biodiversity Action</h2> <p><strong>Framework ID:</strong> <code>framework_biodiversity_implementation</code><br> <strong>Document type:</strong> Tier 2 Foundational Application Layer — Core Governance Document<br> <strong>Version:</strong> 1.1.1<br> <strong>Date:</strong> 2026-08-01<br> <strong>Status:</strong> Controlled constitutional successor — cluster-conformant patch <strong>Conforms to:</strong> <code>CERGTA/0.1</code><br> <strong>Supersedes:</strong> Global Governance Biodiversity Implementation Framework v1.0<br> <strong>Authority effect:</strong> None until lawfully adopted in a jurisdiction</p> <hr> <h2>0. Controlled successor notice</h2> <p>Biodiversity v1.1 preserves the source framework’s purpose: Indigenous-led stewardship, ecosystem rights, restoration, economic transition, community monitoring, just transition, and real accountability for severe ecological harm. It replaces the v1.0 assumption that a biodiversity body, score, threshold, future date, pilot, or coalition can move directly from ecological concern to personhood, veto, guardian appointment, payment, market exclusion, emergency deployment, prosecution, or punishment.</p> <blockquote><p><strong>Biodiversity urgency does not create biodiversity jurisdiction.</strong></p></blockquote> <blockquote><p><strong>Observation is not attribution. Attribution is not legal recognition. Recognition is not title. Guardianship is not regulation. Stewardship is not payment. Certification is not market exclusion. Allegation is not guilt. Emergency support is not command.</strong></p></blockquote> <p>This framework may coordinate, observe, advise, build capacity, support affected Indigenous nations and communities, administer programmes or funds where separately chartered, facilitate restoration, prepare lawful records, and refer matters to competent authorities. It cannot create a global ecological sovereign, grant legal personhood, appoint guardians, transfer title, issue universal permits or tariffs, prosecute, blacklist, freeze funds, seize assets, declare emergencies, or command force.</p> <h2>1. Source freeze and controlling instruments</h2> <table><thead><tr><th>Instrument</th><th>File</th><th>SHA-256</th></tr></thead><tbody><tr><td>Biodiversity Implementation Framework v1.0</td><td>v1.0(4)_2.md</td><td><code>ce90f493e735ccbf3e0a7cde77e9d813c3e1d874d87a4078b3ab554c6c32c772</code></td></tr><tr><td>Commons/Ecological Authority Audit v0.1</td><td>commons-ecological-authority-cluster-constitutional-audit-v0.1.md</td><td><code>974dfd8dd4bf5b623bd5e7e544b7afdbbd89869b66f107db293cfe6af67a043b</code></td></tr><tr><td>CERGTA/0.1</td><td>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</td><td><code>3c45e37c834c727471657fc91149edbe3011137562c2dd73e54b20226c92589b</code></td></tr><tr><td>EIOI v2.7</td><td>ecological-intelligence-observation-interpretation-layer-v2.7.md</td><td><code>41cb7e607e8c3f8776ca74f3ba46ab0ff6bcce94fc24b35178fc4cd94d80d9a2</code></td></tr><tr><td>Planetary Health v0.9</td><td>planetary-health-governance-framework-v0.9.md</td><td><code>259083f6039180b4532ae168ff441245e526570c6442371814cbb238e669dc13</code></td></tr><tr><td>Hearthstone v2.0</td><td>hearthstone-protocol-v2.0.md</td><td><code>b6d50549977a3e50be6726bb5b1b94debddc3fb4d67aff1d2f9af08da65b1b2c</code></td></tr><tr><td>Water & Sanitation v5.2</td><td>water-sanitation-governance-framework-v5.2.md</td><td><code>3612de56de57d1940b278a7e7269588fc08cd964fd97bc33b8ebe8f7d7d69b97</code></td></tr><tr><td>Indigenous Sovereignty & Planetary Healing v1.1</td><td>indigenous-sovereignty-planetary-healing-v1.1.md</td><td><code>2e62ba2c00048ce20e4c9df7ffb9ce0338e358ee866e515bf102f4cc4e49df22</code></td></tr><tr><td>Justice Systems v1.4</td><td>justice-systems-framework-v1.4.md</td><td><code>08a8fdc78d6cd3928178cb5d98fdf8325b1fd4c9f016bb0c872e6b56b87d3ee4</code></td></tr><tr><td>ECRC/0.1</td><td>emergency-catastrophic-risk-continuity-interface-specification-v0.1.md</td><td><code>c673742b1317c7169d4b8226118478c990e9a3d05084b2dc5ac9ad2f1971163c</code></td></tr><tr><td>SCPA/0.1</td><td>security-coercion-protective-action-interface-specification-v0.1.md</td><td><code>b8f1dd0f676044542a23184f52200e50b106a798545c7c57119ded2c439b6299</code></td></tr></tbody></table> <p>A successor source or external framework does not enter this release merely because it has a higher version number or similar title. Compatibility requires controlled review and updated pins.</p> <p>This table is a <strong>provenance record</strong>: it identifies the exact texts read and audited when this successor was drafted. It is not the operative dependency set. The instruments this patch interoperates with are listed in Appendix A.1, and the authoritative machine-readable set is the cluster registry named in A.4. Where the two differ, A.1 governs. Digests are content hashes and remain valid under renaming; a filename here identifies an instrument, not a storage location.</p> <h2>2. Vision and constitutional purpose</h2> <p>Biodiversity loss is a governance failure rooted in extractive incentives, fragmented jurisdiction, colonial dispossession, unaccountable supply chains, weak protection of ecological relationships, and the systematic undervaluation of stewardship. The answer is not to replace private extraction with unbounded ecological administration. The answer is to build lawful, plural, reviewable institutions that can protect ecosystems while preserving affected peoples’ authority, human rights, livelihoods, animal welfare, scientific humility, and the possibility of correction.</p> <p>The framework’s purpose is to connect five functions without merging them:</p> <ol><li><strong>ecological knowledge</strong> from EIOI, affected nations, communities, science, and lawful monitoring;</li> <li><strong>rights and guardianship pathways</strong> through CERGTA and competent legal authorities;</li> <li><strong>stewardship and restoration programmes</strong> through locally grounded, affected-nation-led institutions;</li> <li><strong>economic transition</strong> through separately authorized AUBI, finance, subsidy, procurement, and trade systems;</li> <li><strong>accountability and remedy</strong> through independent investigation, adjudication, restoration, appeal, and—where required—SCPA-governed execution.</li></ol> <h2>3. Core principles</h2> <h3>3.1 Affected-nation authority</h3> <p>The specific affected Indigenous nation or nations determine their representatives, law, territorial and relational authority, consent requirements, protected knowledge, governance forms, and whether to engage. Global Indigenous representation inside the BCT strengthens the BCT’s legitimacy but cannot provide FPIC for another people.</p> <h3>3.2 Rights of nature through lawful recognition</h3> <p>Ecosystems may receive legal rights and standing where competent law provides. Biodiversity institutions may support petitions and evidence but cannot create personhood by resolution, target, dashboard, or threshold.</p> <h3>3.3 Observation–consequence separation</h3> <p>Ecological observations, citizen science, digital twins, satellite data, AI classifications, Bio-Credits, BHI modules, and degradation thresholds may trigger review. They do not themselves create legal rights, guardians, permits, vetoes, funding outcomes, market restrictions, guilt, or emergency power.</p> <h3>3.4 Precaution with due process</h3> <p>Precaution may justify enhanced study, monitoring, interim non-prejudice, or a request for temporary protection. It does not erase jurisdiction, affected-nation authority, participation, proportionality, review, expiry, or remedy.</p> <h3>3.5 Stewardship with livelihoods and animal welfare</h3> <p>Restoration and conservation must address workers, farmers, fishers, residents, customary users, food systems, accessibility, and individual-animal welfare. Ecological improvement cannot be measured solely by aggregate habitat outcomes while localized burdens disappear from view.</p> <h3>3.6 Just transition before withdrawal</h3> <p>No ban, subsidy phase-out, procurement exclusion, protected-area transition, or industry conversion is constitutionally complete without lawful authority, affected-worker and community analysis, alternatives, material support, sequencing, review, and remedy.</p> <h3>3.7 No ecosystem collateralization</h3> <p>An ecosystem’s legal rights, personhood, sacred status, or restoration need cannot be pledged as collateral, monetized as a waiver, or extinguished through a bond, debt swap, credit, certification, or investment contract.</p> <h3>3.8 Open tools, protected knowledge</h3> <p>Methods, public standards, and non-sensitive tools should be open and accessible. Traditional, sacred, genetic, personal, worker, commercial, and security-sensitive data remain purpose-limited and protected.</p> <h3>3.9 Subsidiarity and transboundary coordination</h3> <p>Action should occur at the lowest competent level while recognizing that migratory species, watersheds, oceans, atmospheric effects, and supply chains cross borders. Coordination does not create sovereignty; every participant retains only lawfully delegated power.</p> <h3>3.10 Every authority ends</h3> <p>Every mandate, grant, restriction, investigation, mission, certification, guardianship, and programme has an expiry, review, termination, succession, data-disposition, correction, and remedy path.</p> <h2>4. Governance architecture</h2> <h3>4.1 Global Biodiversity Commons Trust (BCT)</h3> <p>The BCT is retained as a <strong>non-sovereign coordination and programme institution</strong>. It is not the trustee or owner of the biosphere, the universal representative of ecosystems, or a court.</p> <p>Its possible functions, only when separately chartered, include:</p> <ul><li>coordinate voluntary and lawfully adopted biodiversity programmes;</li> <li>publish model standards and interoperability guidance;</li> <li>support ecological-rights petitions without deciding them;</li> <li>maintain public programme and method registries;</li> <li>facilitate technical assistance and peer learning;</li> <li>administer the Global Biodiversity Fund through an independently constituted financial function;</li> <li>commission transparent programme evaluation;</li> <li>support affected Indigenous nations, communities, guardians, and restoration bodies at their request;</li> <li>liaise with existing international and regional bodies.</li></ul> <p>It may not:</p> <ul><li>ratify ecosystem personhood;</li> <li>appoint guardians;</li> <li>determine Indigenous consent or representation;</li> <li>own ecosystems or transferred land by default;</li> <li>issue binding permits, quotas, tariffs, sanctions, or trade restrictions;</li> <li>investigate or adjudicate alleged violations;</li> <li>declare emergencies or command response teams;</li> <li>order search, seizure, arrest, detention, force, cyber action, or asset freezing.</li></ul> <h4>4.1.1 Functional separation</h4> <p>BCT governance, scientific advice, Indigenous-nation liaison, programme administration, fund custody, procurement, audit, complaints, rights-review support, and enforcement referrals must be structurally separated. A member who participates in grant approval, certification, investigation support, or a contested recommendation must disclose conflicts and recuse where necessary.</p> <h4>4.1.2 Representation</h4> <p>Indigenous, scientific, youth, community, worker, disability, animal-welfare, and affected-region representation is required for BCT legitimacy. Numerical seat allocations govern the BCT’s own internal decisions only. They do not create authority over affected nations, local governments, titleholders, guardians, courts, or communities.</p> <h3>4.2 Global Biodiversity Fund</h3> <p>The Fund is a separately constituted public-purpose financial mechanism. Its charter must identify contributors, custodian, eligible uses, allocation criteria, conflicts, beneficial ownership, procurement, reserves, audit, suspension, appeal, restitution, insolvency, and dissolution.</p> <p>A BCT programme recommendation is not a grant decision. A biodiversity score is not payment eligibility. A funding condition cannot require waiver of Indigenous claims, protected knowledge, legal rights, essential services, or access to remedy.</p> <h3>4.3 Regional Biodiversity Hubs</h3> <p>Regional Hubs are implementation and capacity institutions grounded in host jurisdictions and affected-nation relationships. Their possible functions include monitoring support, restoration coordination, community grants, training, low-tech participation, programme reporting, and voluntary stewardship facilitation.</p> <p>A Hub may exercise regulatory, licensing, inspection, fund, or protected-area powers only when the exact power is lawfully delegated and recorded in <code>BIO-11</code>. A Hub cannot make a standard binding merely by adopting language that is “stricter than national regulation.”</p> <h3>4.4 Ecological and Animal-Welfare Ethics Board</h3> <p>The Board is an advisory plural-reasoning body. It examines tensions such as rewilding versus individual-animal welfare, invasive-species intervention, assisted migration, disease control, predator reintroduction, captivity, and habitat management.</p> <p>It must publish:</p> <ul><li>the ecological objective and evidence;</li> <li>the welfare interests and likely harms;</li> <li>affected-nation and community views;</li> <li>alternatives and less harmful methods;</li> <li>uncertainty and dissent;</li> <li>monitoring, review, and stopping conditions.</li></ul> <p>The Board cannot adjudicate rights, appoint guardians, authorize killing or capture, issue a permit, or impose a project outcome.</p> <h3>4.5 Guardians and ecosystem representation</h3> <p>Guardians are appointed only by a competent authority through CERGTA. They hold bounded fiduciary duties to the represented ecosystem and may receive instructions from applicable Indigenous law. They do not own the ecosystem or acquire general regulatory, financial, inspection, or enforcement power.</p> <h3>4.6 Independent justice, finance, trade, emergency, and coercion bodies</h3> <p>Adjudication remains with independent competent justice institutions. Financial decisions remain with competent finance and AUBI bodies. Trade and procurement restrictions remain with lawfully constituted trade or procurement authorities. Emergency command remains under CDEE/ECRC. Coercive execution remains under SCPA.</p> <h2>5. Constitutional operating chain</h2> <p>The default sequence is:</p> <ol><li><code>BIO-02</code> ecological or programme intake;</li> <li><code>BIO-03</code> observation and provenance;</li> <li><code>BIO-04</code> data and knowledge controls;</li> <li><code>BIO-05</code> method and threshold specification;</li> <li><code>BIO-06</code> interpretation, alternatives, uncertainty, and dissent;</li> <li><code>BIO-07</code> affected-interest mapping;</li> <li><code>BIO-08</code> affected-nation authority;</li> <li><code>BIO-09</code> participation and support;</li> <li>the appropriate rights, stewardship, economic, inspection, urgent-protection, or accountability route;</li> <li>separate competent decision;</li> <li>implementation under its own clock and mandate;</li> <li>review, correction, remedy, termination, and data disposition.</li></ol> <p>A later step cannot be inferred from completion of an earlier one.</p> <h2>6. Indigenous-led biodiversity governance</h2> <h3>6.1 Territorial and relational authority</h3> <p>In affected Indigenous territories and relationships, the framework follows the nation’s own governance, law, protocols, and decision makers. “Indigenous-led” cannot be satisfied merely through BCT seat percentages, global advisory councils, outside elders, or generic BAZ structures.</p> <h3>6.2 FPIC and opt-out</h3> <p>FPIC applies where required by the affected nation and applicable law. Refusal, withdrawal, or non-engagement carries no penalty and cannot justify loss of funding, services, monitoring support, legal standing, or environmental protection.</p> <h3>6.3 Traditional Knowledge and benefit sharing</h3> <p>Traditional Knowledge may be public, community-governed, restricted, sacred, or non-disclosable. The affected nation decides permitted use, attribution, benefit sharing, derivatives, publication, retention, return, and deletion. A biodiversity model cannot silently encode protected knowledge into a public score or product passport.</p> <h3>6.4 Internal plurality and competing claims</h3> <p>The framework must not assume that a nation, community, clan, family, youth body, women’s body, customary institution, or elected government speaks with one voice. <code>BIO-08</code> and <code>BIO-22</code> record internal plurality and prevent framework convenience from extinguishing disagreement.</p> <h2>7. Ecosystem-rights implementation</h2> <h3>7.1 Petition and review</h3> <p>Communities, affected nations, guardians, public bodies, or other persons with lawful standing may submit <code>BIO-13</code>. The petition identifies the entity, proposed rights, legal basis, ecological and cultural evidence, affected interests, requested relief, and what the petition does not decide.</p> <h3>7.2 Recommendation</h3> <p><code>BIO-14</code> provides an advisory record. It includes EIOI evidence, boundary uncertainty, affected-nation law, human and Indigenous rights, animal-welfare implications, conflicts, alternatives, dissent, and review conditions.</p> <h3>7.3 Recognition</h3> <p>Only a competent legal authority may create <code>CERGTA-13</code>. BCT, PHC, a Regional Hub, a dashboard, or a pilot cannot “ratify” personhood. The recognition decision must specify exact rights, legal jurisdiction, conflicts, remedies, duration or amendment process, and non-derogation.</p> <h3>7.4 Boundary and title</h3> <p>The ecological entity and its legal boundary require <code>BIO-17</code>. Rights recognition does not transfer adjacent land, infrastructure, concessions, permits, resource title, or public authority. Title, tenure, rematriation, and compensation remain under CERGTA and Hearthstone.</p> <h3>7.5 No automatic rights escalation</h3> <p>The v1.0 Rights Escalation Ladder is retired as a self-executing mechanism. A degradation threshold may:</p> <ul><li>trigger intensified monitoring;</li> <li>require a published review;</li> <li>support a rights-review recommendation;</li> <li>support a request for temporary urgent protection.</li></ul> <p>It cannot automatically create a veto, suspend a permit, close a facility, appoint a guardian, or order enforcement.</p> <h2>8. Stewardship, protected areas, and restoration</h2> <h3>8.1 Claim and interest mapping</h3> <p>A protected-area, restoration, biocultural, or stewardship proposal starts with <code>BIO-21</code> and <code>BIO-22</code>. The process must identify customary uses, housing, workers, farmers, fishers, tenure, concessions, debt, tourism, food systems, sacred relations, animal-welfare interests, and transboundary effects.</p> <h3>8.2 Interim protection</h3> <p>Where irreversible loss is plausible, <code>BIO-23</code> may seek narrow non-prejudice protection. The request must be least restrictive, time limited, reviewed, and without prejudice to final rights, title, guilt, or compensation.</p> <h3>8.3 Stewardship charter</h3> <p><code>BIO-24</code> defines the steward’s legal source, powers, duties, prohibited acts, affected-nation relationship, budget, participation, conflicts, transparency, review, succession, and dissolution.</p> <h3>8.4 Restoration plan</h3> <p><code>BIO-25</code> includes ecological methods, Indigenous and local knowledge, workers and livelihoods, species and individual-animal welfare, food and water systems, accessibility, budget, monitoring, stopping conditions, and long-term maintenance.</p> <h3>8.5 Performance and correction</h3> <p><code>BIO-26</code> separates stewardship performance from external shocks and inherited degradation. No score, model, or audit automatically suspends a steward or freezes funds. <code>BIO-27</code> requires notice, support, correction, independent review, interim relief, succession, and remedy.</p> <h3>8.6 Protected-area non-displacement</h3> <p>Conservation cannot be implemented through silent displacement, criminalization of customary subsistence, deprivation of essential services, or transfer of authority to an external NGO. Any restriction or relocation requires separate lawful authority, necessity, alternatives, compensation, livelihood continuity, appeal, and remedy.</p> <h2>9. Species, habitat, and precautionary interventions</h2> <h3>9.1 Intervention review</h3> <p><code>BIO-29</code> governs rewilding, predator reintroduction, invasive-species control, assisted migration, disease response, captive breeding, culling, contraception, habitat engineering, and analogous interventions. It requires necessity, alternatives, welfare analysis, affected-nation and community authority, uncertainty, monitoring, duration, review, and stopping rules.</p> <h3>9.2 Emerging technologies</h3> <p><code>BIO-30</code> addresses gene drives, synthetic biology, de-extinction, large-scale geoengineering, autonomous ecological control systems, and other high-uncertainty interventions. Biodiversity institutions may recommend precautionary controls or a moratorium review. They cannot themselves authorize or prohibit the activity unless separately empowered by applicable law.</p> <h3>9.3 Precaution does not reverse the burden into guilt</h3> <p>A proponent may bear evidentiary duties before receiving a permit. That does not permit a biodiversity body to presume criminal liability, seize equipment, or impose punishment without a separate legal route.</p> <h2>10. UBES and stewardship rewards</h2> <h3>10.1 Activity verification</h3> <p><code>BIO-31</code> records the stewardship activity and ecological effect. It distinguishes:</p> <ul><li>work performed;</li> <li>observed ecological change;</li> <li>causal attribution;</li> <li>participant identity;</li> <li>community or affected-nation verification;</li> <li>uncertainty and duplication risk;</li> <li>accessibility and low-tech evidence;</li> <li>correction status.</li></ul> <h3>10.2 Financial decision</h3> <p><code>BIO-32</code> routes the verified activity to the competent AUBI or financial authority. The receiving authority independently decides eligibility, amount, timing, withholding, overpayment, fraud review, appeal, and data disposition.</p> <h3>10.3 Non-retaliation and essential security</h3> <p>A person cannot lose essential income, water, food, housing, healthcare, legal protection, or community standing merely because ecological evidence is disputed, a record is corrected, or they decline further data collection.</p> <h2>11. Economic transformation</h2> <h3>11.1 Harmful-subsidy reform</h3> <p>The source target of redirecting <code>$250 billion</code> is retained as an aspirational programme target, not a standing appropriation. <code>BIO-33</code> requires identification of legal budget authority, actual subsidy flows, beneficial owners, ecological effects, workers, communities, food and energy security, alternatives, transition finance, phase-out timing, review, and remedy.</p> <h3>11.2 Biodiversity grants and impact bonds</h3> <p><code>BIO-34</code> separates programme recommendation from financial approval. Every instrument must disclose investor return, public guarantee, ecological method, distribution of benefits and risks, community and affected-nation authority, procurement, conflicts, failure conditions, audit, and exit.</p> <p>An ecosystem, rights-holder status, sacred relationship, or future restoration obligation cannot be collateral.</p> <h3>11.3 Debt-for-nature and debt-for-stewardship agreements</h3> <p><code>BIO-35</code> separates debt relief from ecological title and governance. A debt agreement cannot:</p> <ul><li>waive affected-nation claims or consent;</li> <li>designate a protected area by itself;</li> <li>transfer land to the creditor or BCT;</li> <li>make an ecosystem collateral;</li> <li>create an automatic market sanction;</li> <li>eliminate review or remedy.</li></ul> <h3>11.4 Bio-Credits and product passports</h3> <p><code>BIO-36</code> separates:</p> <ol><li>method and baseline;</li> <li>observed ecological claim;</li> <li>verifier and audit;</li> <li>certification decision;</li> <li>product-passport field;</li> <li>correction and expiry;</li> <li>any later procurement or market decision.</li></ol> <p>A negative score is not a market-exclusion order.</p> <h3>11.5 Shadow pricing</h3> <p>Shadow pricing may illuminate ecological dependencies and distributional choices. It does not determine inherent worth, legal damages, compensation, title, permit conditions, taxes, or penalties without a separate lawful decision.</p> <h2>12. Procurement, trade, and supply-chain accountability</h2> <h3>12.1 Transparency</h3> <p>Digital Product Passports and supply-chain records must disclose methodology, source, uncertainty, ownership, correction status, and scope. Protected Traditional Knowledge, personal data, whistleblower identity, and security-sensitive information remain restricted.</p> <h3>12.2 Restriction request</h3> <p><code>BIO-37</code> may request a CERGTA-44 procurement, market, trade, listing, or delisting decision. The competent authority must independently establish jurisdiction, legal basis, individualized evidence, proportionality, alternatives, worker and community effects, essential-goods safeguards, notice, review, expiry, correction, and delisting.</p> <h3>12.3 No collective punishment</h3> <p>A restriction cannot punish an entire nation, Indigenous people, region, community, small producer class, or workforce because of an aggregate national or corporate score when the affected actors and supply paths can be distinguished.</p> <h2>13. Monitoring, inspection, investigation, and evidence</h2> <h3>13.1 Monitoring</h3> <p>Routine ecological observation follows <code>BIO-03</code> and <code>BIO-04</code>. It creates no entry, search, production, or interrogation power.</p> <h3>13.2 Inspection</h3> <p><code>BIO-38</code> requires lawful authority, exact premises or activity, purpose, notice or justified exception, scope, sampling, biosecurity, privacy, protected knowledge, report, challenge, and closure.</p> <h3>13.3 Investigation</h3> <p><code>BIO-39</code> opens a distinct investigation into alleged illegal extraction, subsidy fraud, data manipulation, FPIC violation, biodiversity harm, or analogous conduct. Advocacy, monitoring, certification, and grant administration cannot silently become investigation.</p> <h3>13.4 Evidence and scientific attribution</h3> <p><code>BIO-40</code> preserves custody, analytical methods, uncertainty, alternative causes, exculpatory material, access, challenge, correction, and admissibility. An AI classification, model output, or Bio-Credit score is not by itself proof of legal responsibility.</p> <h2>14. Ecocide and justice interface</h2> <h3>14.1 No framework-created offence or universal penalty</h3> <p>Biodiversity v1.1 does not define a universally active ecocide crime, predetermine ICC jurisdiction, prescribe automatic <code>$1 million–$10 million</code> fines, or establish officer liability. Those questions belong to the competent legal system and the controlling law.</p> <h3>14.2 Adjudication referral</h3> <p><code>BIO-43</code> identifies the allegation, legal theory, parties, affected ecosystems and communities, evidence, uncertainty, exculpatory material, requested remedy, jurisdictional questions, access restrictions, and challenge route. The recipient independently decides whether to accept the matter.</p> <h3>14.3 Enforcement</h3> <p>A judgment does not execute itself. Search, seizure, arrest, restraint, custody, force, cyber action, border action, and asset freezing require <code>CERGTA-48</code> and separate SCPA authority.</p> <h2>15. Whistleblowers and community monitors</h2> <p><code>BIO-44</code> provides confidential reporting, anti-retaliation, legal assistance, livelihood support, safe contact, correction, and remedy. Financial rewards, where separately authorized, are not conditioned on a conviction and do not make an allegation more credible. Support does not require continued cooperation, confrontation, or public disclosure.</p> <h2>16. Urgent ecological protection and emergency assistance</h2> <h3>16.1 Urgent protection</h3> <p>Where imminent irreversible harm is plausibly established, <code>BIO-41</code> may request <code>CERGTA-42</code>. The authorization must identify the exact legal authority, ecological entity, act, alternatives, affected people and workers, service continuity, duration, review, expiry, restoration, and remedy.</p> <p>The source rule that <code>&gt;10% habitat loss</code> automatically triggers a response is retired. A percentage may indicate urgency but cannot create jurisdiction.</p> <h3>16.2 Biodiversity Emergency Assistance Teams</h3> <p>The source term <strong>Biodiversity SWAT Teams</strong> is retired. <code>BIO-42</code> establishes optional civilian technical-assistance teams for ecological assessment, wildlife rescue, habitat stabilization, seed or genetic-material protection, community support, restoration planning, and logistics.</p> <p>Teams:</p> <ul><li>operate only after acceptance by a competent CDEE/ECRC command;</li> <li>remain within a written mission;</li> <li>follow affected-nation and host-jurisdiction law;</li> <li>cannot search, seize, arrest, detain, use force, gather intelligence, operate checkpoints, or command other agencies;</li> <li>have stop-work, worker-safety, termination, data-disposition, and remedy rules.</li></ul> <h3>16.3 Emergency finance</h3> <p>No automatic five-percent fund release occurs. Emergency finance requires an identified competent authority, amount, purpose, custodian, procurement route, audit, expiry, correction, and restitution.</p> <h2>17. Cultural mobilization and public communication</h2> <p>Campaigns, restoration festivals, art residencies, education, games, storybanks, and public dashboards remain non-governance tools. They must not expose protected knowledge, prejudge legal cases, target dissenters, manipulate affected communities, or represent programme targets as legal facts.</p> <h2>18. Implementation pathway</h2> <h3>18.1 Adoption states</h3> <p>Every mechanism is labelled as one of:</p> <ul><li><code>proposed</code>;</li> <li><code>advisory</code>;</li> <li><code>voluntarily_adopted</code>;</li> <li><code>contractually_binding</code>;</li> <li><code>locally_enacted</code>;</li> <li><code>nationally_enacted</code>;</li> <li><code>treaty_active</code>;</li> <li><code>suspended</code>;</li> <li><code>expired</code>;</li> <li><code>terminated</code>.</li></ul> <h3>18.2 Bootstrap phase</h3> <p>Regional and affected-nation-led initiatives may begin with voluntary monitoring, restoration, community grants, low-tech tools, legal support, and model-law development. They do not acquire personhood, guardian, market, investigation, or emergency powers merely because global institutions are absent.</p> <h3>18.3 Pilots</h3> <p>Pilots in Costa Rica, Bhutan, Palau, or elsewhere may test methods, participation, records, restoration, finance, and legal pathways under local authority. A pilot target such as five ecosystems with personhood is an evaluation target, not authority to create personhood.</p> <h3>18.4 Scaling</h3> <p>Scale follows demonstrated legitimacy, ecological benefit, rights protection, affected-nation authority, institutional capacity, correction, and remedy—not only percentages of land protected, score improvement, capital raised, or coalition size.</p> <h3>18.5 Coalition and treaty activation</h3> <p>A coalition of twenty or more nations may establish cooperative instruments among its members. Coalition size does not itself make BCT standards, rights recommendations, trade measures, or programme decisions binding. Each power must be enacted under the applicable legal route.</p> <h2>19. What success looks like under v1.1</h2> <h3>19.1 A river seeks legal standing</h3> <p>Community and affected-nation petitioners submit <code>BIO-13</code>; EIOI evidence and dissent are recorded in <code>BIO-14</code>; the competent jurisdiction creates a rights decision; the legal boundary and guardian are separately constituted. Adjacent land and infrastructure do not silently transfer.</p> <h3>19.2 Traditional farming receives stewardship support</h3> <p>The farmer’s activity and ecological effect are verified in <code>BIO-31</code>. AUBI independently determines payment through <code>BIO-32</code>. Traditional Knowledge remains under the community’s rules, and payment is not conditioned on surrendering it.</p> <h3>19.3 A reef reaches a critical bleaching threshold</h3> <p>The threshold triggers enhanced monitoring, a published review, and—where imminent irreversible harm exists—an urgent-protection request. Permits are not automatically suspended, but the competent authority must consider the evidence promptly and explain its decision.</p> <h3>19.4 A palm-oil supply chain receives a negative ecological assessment</h3> <p>The product-passport field shows its method, source, uncertainty, and correction status. A procurement or market authority may begin a separate review. Workers, smallholders, food security, affected communities, and regenerative alternatives are considered before any restriction.</p> <h3>19.5 A community species count reveals a previously unseen decline</h3> <p>The teenager’s observation has epistemic value and enters <code>BIO-03</code>. It contributes to ecological interpretation and possibly a rights petition. It does not alone establish legal personhood, a criminal offence, or a payment.</p> <h3>19.6 A debt swap funds long-term restoration</h3> <p>The agreement reduces debt and finances restoration, but does not make the ecosystem collateral, waive affected-nation claims, or bypass a lawful protected-area or stewardship process.</p> <h2>20. Canonical Biodiversity record catalogue</h2> <table><thead><tr><th>ID</th><th>Record</th><th>Purpose</th></tr></thead><tbody><tr><td>BIO-01</td><td>Constituting Instrument, Jurisdiction, Adoption, and Power Register</td><td>Pins the exact legal source, territorial and subject-matter jurisdiction, adoption state, delegated powers, exclusions, review, expiry, and authority return.</td></tr><tr><td>BIO-02</td><td>Biodiversity Programme, Ecosystem Candidate, Habitat, Species, and Boundary Intake</td><td>Identifies the ecological entity, habitat, species, programme, proposed area, existing legal designations, affected uses, and boundary uncertainty without creating rights or restrictions.</td></tr><tr><td>BIO-03</td><td>Biodiversity Observation, Monitoring, Sampling, and Provenance</td><td>Records satellite, field, citizen-science, acoustic, genetic, Indigenous, community, and low-tech observations with method, source, quality, uncertainty, and chain of custody.</td></tr><tr><td>BIO-04</td><td>Ecological Data, Traditional Knowledge, Sacred Knowledge, Access, and Retention</td><td>Defines purpose, affected-nation authority, consent, benefit sharing, confidentiality, access class, derivative use, correction, return, deletion, and public-memory rules.</td></tr><tr><td>BIO-05</td><td>Biodiversity Indicator, Baseline, Threshold, Weighting, and Model Specification</td><td>Publishes definitions, spatial and temporal scale, baseline, variables, thresholds, weighting, validation, sensitivity, uncertainty, gaming risks, and permitted advisory uses.</td></tr><tr><td>BIO-06</td><td>Biodiversity Interpretation, Attribution, Alternatives, and Dissent</td><td>Separates observed fact from interpretation, causal attribution, forecast, scenario, uncertainty, alternative explanations, minority analysis, and correction status.</td></tr><tr><td>BIO-07</td><td>Affected Persons, Communities, Nations, Workers, Users, Species, and Ecosystems Map</td><td>Identifies affected Indigenous nations, residents, customary users, workers, farmers, fishers, enterprises, future generations, animal-welfare interests, ecosystems, and transboundary parties.</td></tr><tr><td>BIO-08</td><td>Affected Indigenous Nation, Applicable Law, FPIC, and Non-Engagement Record</td><td>Identifies the specific affected nation or nations, their own representatives and law, territorial and relational authority, consent requirements, internal plurality, protected knowledge, and right not to participate.</td></tr><tr><td>BIO-09</td><td>Notice, Participation, Accessibility, Counsel, and Community Support</td><td>Records timely notice, translation, disability access, low-bandwidth participation, counsel, technical support, childcare, travel, response time, dissent, and protection from retaliation.</td></tr><tr><td>BIO-10</td><td>Global Biodiversity Commons Trust Charter and Functional-Separation Register</td><td>Defines the BCT as a coordination, programme, and separately chartered fund-administration institution; separates standards, grants, rights review, procurement, investigation, adjudication, and enforcement.</td></tr><tr><td>BIO-11</td><td>Regional Biodiversity Hub Charter, Delegation, and Local Accountability</td><td>Defines each Hub’s lawful host jurisdiction, delegated functions, affected-nation relationship, public accountability, data limits, financial controls, service duties, expiry, and withdrawal.</td></tr><tr><td>BIO-12</td><td>Ecological and Animal-Welfare Conflict Advisory Review</td><td>Provides transparent, plural analysis of ecosystem, species, and individual-animal welfare tensions; records alternatives and dissent without adjudicating rights or authorizing intervention.</td></tr><tr><td>BIO-13</td><td>Ecological Rights Review Petition and Standing</td><td>Receives a petition for rights review while preserving legal standing questions, competing claims, boundaries, and non-derogable human and Indigenous rights.</td></tr><tr><td>BIO-14</td><td>Ecological Rights Review Recommendation, Alternatives, and Dissent</td><td>Prepares a bounded advisory recommendation using EIOI evidence, affected-nation law, participation, uncertainty, conflict analysis, and minority reports.</td></tr><tr><td>BIO-15</td><td>Lawful Ecosystem Rights Recognition Interface</td><td>Links to a separately competent CERGTA-13 recognition decision and records its exact rights, limits, jurisdiction, conflicts, review, expiry, and remedy.</td></tr><tr><td>BIO-16</td><td>Rights Catalogue, Priority, Conflict, and Non-Derogation</td><td>Records which rights were lawfully recognized, how conflicts are handled, what is non-derogable, and what the recognition does not imply about title, guardianship, permits, or enforcement.</td></tr><tr><td>BIO-17</td><td>Ecological and Legal Boundary Constitution</td><td>Records the competent decision defining the represented ecological entity and legal boundary, including hydrological or migratory dynamics, uncertainty, overlapping jurisdictions, and revision.</td></tr><tr><td>BIO-18</td><td>Guardian Nomination, Eligibility, and Conflict Review</td><td>Records nominations, affected-nation instructions, community legitimacy, expertise, independence, conflicts, accessibility, budget, and reasons without making an appointment.</td></tr><tr><td>BIO-19</td><td>Guardian Appointment, Mandate, Standing, and Fiduciary Duty</td><td>Records the competent appointment, represented entity, legal standing, instructions, duties, prohibited acts, reporting, duration, liability, and succession.</td></tr><tr><td>BIO-20</td><td>Guardian Complaint, Review, Removal, Substitution, and Liability</td><td>Provides independent complaint, recusal, removal, substitution, liability, continuity, and remedy without transferring title or regulatory power.</td></tr><tr><td>BIO-21</td><td>Protected-Area, Conservation, Restoration, or Biocultural Claim Intake</td><td>Records the requested protection, restoration, stewardship, title, access, or reparative relief without deciding the claim or extinguishing existing interests.</td></tr><tr><td>BIO-22</td><td>Competing Claims, Uses, Rights, Tenure, and Non-Extinguishment Map</td><td>Maps Indigenous, customary, public, private, community, livelihood, ecological, animal-welfare, creditor, tenant, worker, and transboundary interests.</td></tr><tr><td>BIO-23</td><td>Interim Non-Prejudice and Anti-Dissipation Request</td><td>Requests narrow temporary protection against irreversible ecological loss or asset dissipation without deciding title, guilt, permanent closure, or final land use.</td></tr><tr><td>BIO-24</td><td>Biodiversity Stewardship Charter, Purpose, Powers, and Prohibited Acts</td><td>Defines the steward, legal basis, purpose, ecological duties, affected-nation authority, participation, budget, conflicts, prohibited acts, review, succession, and dissolution.</td></tr><tr><td>BIO-25</td><td>Restoration and Conservation Plan, Budget, Participation, and Just Transition</td><td>Defines objectives, methods, alternatives, local knowledge, species and welfare effects, workers and livelihoods, budget, milestones, monitoring, review, and exit.</td></tr><tr><td>BIO-26</td><td>Stewardship Performance, External-Shock, Metric-Gaming, and Context Review</td><td>Assesses performance using versioned evidence while separating management failure from wildfire, climate shock, upstream harm, conflict, inherited degradation, and metric gaming.</td></tr><tr><td>BIO-27</td><td>Stewardship Correction, Capacity Support, Suspension, Succession, and Dissolution</td><td>Records graduated correction, support, independent review, interim relief, suspension, lawful replacement, succession, dissolution, restoration, and remedy.</td></tr><tr><td>BIO-28</td><td>Biodiversity Standard, Target, Plan, and Legal Adoption Status</td><td>Separates scientific advice, programme targets, voluntary adoption, contractual commitments, local enactment, treaty activation, suspension, expiry, and termination.</td></tr><tr><td>BIO-29</td><td>Species, Habitat, Rewilding, Invasive-Species, and Welfare Intervention Review</td><td>Assesses intervention necessity, uncertainty, less harmful alternatives, animal welfare, ecosystem effects, Indigenous and community authority, duration, monitoring, and review.</td></tr><tr><td>BIO-30</td><td>Precautionary Technology, Gene Drive, De-Extinction, and Geoengineering Review</td><td>Provides advisory precautionary assessment and recommends research controls or a moratorium request; it does not itself prohibit, seize, shut down, or authorize intervention.</td></tr><tr><td>BIO-31</td><td>UBES Stewardship Activity, Contribution, and Ecological-Effect Verification</td><td>Records the claimed activity, participant, method, ecological effect, uncertainty, community verification, duplication risk, accessibility, correction, and prohibited inferences.</td></tr><tr><td>BIO-32</td><td>UBES Eligibility, Payment, Withholding, Appeal, and Data-Disposition Referral</td><td>Separates verified activity from a competent AUBI or financial decision, with eligibility criteria, amount, fraud safeguards, notice, appeal, correction, non-retaliation, and closure.</td></tr><tr><td>BIO-33</td><td>Harmful Subsidy Review, Beneficial-Owner Map, and Just-Transition Plan</td><td>Identifies subsidy flows, beneficiaries, ecological harm, workers and communities, legal authority, alternatives, transition support, phase-out sequence, review, and remedy.</td></tr><tr><td>BIO-34</td><td>Biodiversity Grant, Impact Bond, Guarantee, or Programme-Finance Decision</td><td>Records the competent financial authority, instrument, risk, beneficiaries, conditions, ecological claims, community consent, investor rights, non-collateralization of ecosystems, audit, and exit.</td></tr><tr><td>BIO-35</td><td>Debt-for-Nature or Debt-for-Stewardship Agreement</td><td>Separates sovereign or private debt restructuring from ecological title, Indigenous claims, conservation commitments, community benefits, enforcement, monitoring, review, and remedy.</td></tr><tr><td>BIO-36</td><td>Bio-Credit Method, Certification, Product-Passport, and Correction Record</td><td>Separates ecological method, verified claim, certification, product-passport field, issuer, audit, uncertainty, correction, expiry, and prohibited market inferences.</td></tr><tr><td>BIO-37</td><td>Procurement, Market, Trade, Listing, or Delisting Restriction Request</td><td>Requests a separately lawful CERGTA-44 decision with individualized basis, supply-chain evidence, essential-goods and worker safeguards, notice, review, expiry, correction, and delisting.</td></tr><tr><td>BIO-38</td><td>Biodiversity Inspection, Entry, Sampling, and Report Authorization</td><td>Defines lawful inspector, place, scope, notice or exception, sampling, privacy, biosecurity, protected knowledge, report, challenge, and closure.</td></tr><tr><td>BIO-39</td><td>Biodiversity Harm, Fraud, Illegal Extraction, or FPIC-Violation Investigation</td><td>Opens a distinct investigation with allegation, authority, parties, methods, source protections, exculpatory duties, duration, review, and closure.</td></tr><tr><td>BIO-40</td><td>Ecological Evidence Custody, Scientific Attribution, and Admissibility</td><td>Maintains evidence identity, custody, method, uncertainty, alternative causes, exculpatory material, access, challenge, correction, and admissibility boundaries.</td></tr><tr><td>BIO-41</td><td>Urgent Ecological Protection Request and Least-Harm Assessment</td><td>Requests a narrow CERGTA-42 action for imminent irreversible harm, identifying authority, exact act, alternatives, workers and communities, service continuity, review, expiry, restoration, and remedy.</td></tr><tr><td>BIO-42</td><td>Biodiversity Emergency Assistance Team Mission and Civilian Support Record</td><td>Defines technical assistance under a competent CDEE/ECRC emergency command; excludes search, seizure, arrest, detention, force, intelligence, border action, and independent command.</td></tr><tr><td>BIO-43</td><td>Ecocide, Rights-Violation, or Biodiversity-Harm Adjudication Referral</td><td>Transfers a bounded allegation and evidence package to a competent justice body without presuming guilt, penalty, jurisdiction, or enforcement.</td></tr><tr><td>BIO-44</td><td>Whistleblower, Community Monitor, Witness, and Source Protection</td><td>Provides safe reporting, confidentiality, anti-retaliation, legal and material support, reward separation, correction, and remedy without purchasing allegations or compelling cooperation.</td></tr><tr><td>BIO-45</td><td>Ecological Restoration, Corrective Action, Requalification, and Verification</td><td>Records lawful restoration duties, responsible parties, methods, affected-nation and community participation, finance, independent verification, requalification, and closure.</td></tr><tr><td>BIO-46</td><td>Appeal, Interim Relief, Complaint, Correction, Restitution, and Compensation</td><td>Provides accessible challenge, counsel, correction, temporary relief, restitution, compensation, public correction, and protection from retaliation.</td></tr><tr><td>BIO-47</td><td>Authority Expiry, Termination, Data Disposition, Succession, and Unresolved-Duty Custody</td><td>Closes programme authority, returns credentials and funds, disposes data, preserves unresolved claims and restoration duties, and prevents residual power.</td></tr><tr><td>BIO-48</td><td>Pilot, Target, Milestone, Coalition, and Power Non-Activation Register</td><td>Records pilots, percentages, future dates, coalition size, model laws, demonstrations, and targets while expressly preventing them from activating legal rights, sanctions, funding, or emergency power.</td></tr></tbody></table> <h2>21. CERGTA common record-header inheritance</h2> <p>Every Biodiversity record contains or inherits all forty CERGTA common fields. A domain form may add fields but may not remove canonical identity, authority, jurisdiction, affected parties, prohibited inferences, access, clocks, challenge, termination, disposition, or remedy.</p> <table><thead><tr><th>#</th><th>Inherited common field</th></tr></thead><tbody><tr><td>1</td><td>record_id</td></tr><tr><td>2</td><td>record_instance_id</td></tr><tr><td>3</td><td>record_version</td></tr><tr><td>4</td><td>status</td></tr><tr><td>5</td><td>created_at</td></tr><tr><td>6</td><td>effective_at</td></tr><tr><td>7</td><td>created_by</td></tr><tr><td>8</td><td>competent_authority</td></tr><tr><td>9</td><td>legal_source</td></tr><tr><td>10</td><td>jurisdiction</td></tr><tr><td>11</td><td>authority_activation_state</td></tr><tr><td>12</td><td>ecological_action_cluster_id</td></tr><tr><td>13</td><td>action_class</td></tr><tr><td>14</td><td>exact_act</td></tr><tr><td>15</td><td>entity_asset_resource_id</td></tr><tr><td>16</td><td>ecological_and_legal_boundary_version</td></tr><tr><td>17</td><td>affected_persons_and_communities</td></tr><tr><td>18</td><td>affected_indigenous_nations</td></tr><tr><td>19</td><td>claimants_and_interest_holders</td></tr><tr><td>20</td><td>linked_records</td></tr><tr><td>21</td><td>source_and_reliability_limits</td></tr><tr><td>22</td><td>uncertainty_and_dissent</td></tr><tr><td>23</td><td>prohibited_inferences</td></tr><tr><td>24</td><td>rights_and_safeguards</td></tr><tr><td>25</td><td>essential_minimums</td></tr><tr><td>26</td><td>consent_fpic_and_nonengagement_status</td></tr><tr><td>27</td><td>access_class</td></tr><tr><td>28</td><td>notice_status</td></tr><tr><td>29</td><td>review_authority</td></tr><tr><td>30</td><td>review_due_at</td></tr><tr><td>31</td><td>expires_at_or_nonexpiry_basis</td></tr><tr><td>32</td><td>challenge_and_interim_relief_route</td></tr><tr><td>33</td><td>termination_trigger</td></tr><tr><td>34</td><td>authority_asset_and_credential_return</td></tr><tr><td>35</td><td>data_disposition_rule</td></tr><tr><td>36</td><td>remedy_route</td></tr><tr><td>37</td><td>supersedes</td></tr><tr><td>38</td><td>superseded_by</td></tr><tr><td>39</td><td>integrity_digest</td></tr><tr><td>40</td><td>public_summary_or_protected_basis</td></tr></tbody></table> <h2>22. Complete CERGTA conformance crosswalk</h2> <table><thead><tr><th>CERGTA</th><th>Canonical record</th><th>Class</th><th>Relationship</th><th>Biodiversity record</th><th>Conformance note</th></tr></thead><tbody><tr><td>CERGTA-01</td><td>Constituting Instrument, Legal Source, Jurisdiction, and Activation Status</td><td>A</td><td>implements</td><td>BIO-01</td><td>All Biodiversity powers require a pinned constituting instrument and adoption state.</td></tr><tr><td>CERGTA-02</td><td>Ecological Entity Candidate, Resource, Asset, and Boundary Intake</td><td>A</td><td>extends</td><td>BIO-02</td><td>Adds species, habitat, programme, protected-area, and restoration-candidate intake.</td></tr><tr><td>CERGTA-03</td><td>Observation, Monitoring, Sampling, and Provenance Record</td><td>A</td><td>implements</td><td>BIO-03</td><td>Monitoring remains evidence, not legal consequence.</td></tr><tr><td>CERGTA-04</td><td>Ecological Data Purpose, Consent, Sovereignty, Access, and Retention Record</td><td>A</td><td>implements</td><td>BIO-04</td><td>Includes Indigenous, sacred, genetic, community, worker, and commercial data controls.</td></tr><tr><td>CERGTA-05</td><td>Indicator, Index, Threshold, Weighting, and Model Specification</td><td>B</td><td>implements</td><td>BIO-05</td><td>Thresholds and scores are versioned advisory instruments.</td></tr><tr><td>CERGTA-06</td><td>Ecological Interpretation, Causal Assessment, and Uncertainty Record</td><td>B</td><td>implements</td><td>BIO-06</td><td>Interpretation, attribution, uncertainty, and dissent remain distinct from observation.</td></tr><tr><td>CERGTA-07</td><td>Traditional Knowledge, Sacred Knowledge, and Epistemic Contribution Record</td><td>B</td><td>implements</td><td>BIO-04, BIO-06, BIO-08</td><td>Traditional and sacred knowledge remain under the affected nation’s authority and may be withheld.</td></tr><tr><td>CERGTA-08</td><td>Affected Persons, Communities, Nations, Users, Workers, and Rights Map</td><td>A</td><td>implements</td><td>BIO-07</td><td>Maps affected humans, nations, livelihoods, species, ecosystems, and welfare interests.</td></tr><tr><td>CERGTA-09</td><td>Affected Indigenous Nation and Applicable-Law Determination</td><td>F</td><td>implements</td><td>BIO-08</td><td>Global Indigenous representation never substitutes for the affected nation.</td></tr><tr><td>CERGTA-10</td><td>Notice, Participation, Accessibility, Counsel, and Support Record</td><td>A</td><td>implements</td><td>BIO-09</td><td>Participation includes accessibility, counsel, technical support, and anti-retaliation.</td></tr><tr><td>CERGTA-11</td><td>Ecological Rights Review Petition and Standing Record</td><td>C</td><td>implements</td><td>BIO-13</td><td>A petition opens review only.</td></tr><tr><td>CERGTA-12</td><td>Rights Review Recommendation and Dissent Record</td><td>C</td><td>implements</td><td>BIO-14</td><td>Biodiversity institutions may recommend but cannot recognize rights.</td></tr><tr><td>CERGTA-13</td><td>Lawful Ecological Rights Recognition Decision</td><td>D</td><td>imports</td><td>BIO-15</td><td>Recognition must come from a separately competent legal authority.</td></tr><tr><td>CERGTA-14</td><td>Rights Catalogue, Priority, Conflict, and Non-Derogation Record</td><td>D</td><td>implements</td><td>BIO-16</td><td>Rights, conflicts, priorities, and non-derogation are explicit.</td></tr><tr><td>CERGTA-15</td><td>Ecological and Legal Boundary Constitution Record</td><td>D</td><td>implements</td><td>BIO-17</td><td>Ecological and legal boundaries require a separate competent decision.</td></tr><tr><td>CERGTA-16</td><td>Guardian Nomination and Eligibility Record</td><td>E</td><td>implements</td><td>BIO-18</td><td>Nomination is not appointment.</td></tr><tr><td>CERGTA-17</td><td>Guardian Appointment, Mandate, and Standing Record</td><td>E</td><td>imports</td><td>BIO-19</td><td>Appointment and standing come from a competent authority, not BCT or a Hub.</td></tr><tr><td>CERGTA-18</td><td>Guardian Fiduciary Duty, Instructions, Conflict, and Recusal Record</td><td>E</td><td>implements</td><td>BIO-19</td><td>Fiduciary duties and instructions are recorded in the appointment mandate.</td></tr><tr><td>CERGTA-19</td><td>Guardian Review, Complaint, Removal, Substitution, and Liability Record</td><td>E</td><td>implements</td><td>BIO-20</td><td>Independent complaint, removal, liability, and succession are preserved.</td></tr><tr><td>CERGTA-20</td><td>Sacred, Cultural, Biocultural, and Inalienability Designation Petition</td><td>F</td><td>imports</td><td>BIO-21, BIO-08</td><td>Biodiversity claims may include biocultural protection; sacred designation requires a separate affected-nation route.</td></tr><tr><td>CERGTA-21</td><td>Sacred, Cultural, Biocultural, and Inalienability Designation Decision</td><td>F</td><td>imports</td><td>BIO-21, BIO-08</td><td>BCT and Hubs do not decide sacredness or inalienability.</td></tr><tr><td>CERGTA-22</td><td>Claim Intake, Standing, and Relief Requested Record</td><td>G</td><td>implements</td><td>BIO-21</td><td>Claim intake does not decide standing or relief.</td></tr><tr><td>CERGTA-23</td><td>Competing Claims, Parties, Interests, and Non-Extinguishment Map</td><td>G</td><td>implements</td><td>BIO-22</td><td>Competing interests remain visible and non-extinguished.</td></tr><tr><td>CERGTA-24</td><td>Historical, Customary, Occupancy, Use, and Documentary Evidence Record</td><td>G</td><td>implements</td><td>BIO-22, BIO-03, BIO-04</td><td>Customary, occupancy, use, scientific, and documentary evidence remain separate and challengeable.</td></tr><tr><td>CERGTA-25</td><td>Interim Non-Prejudice and Anti-Dissipation Protection Record</td><td>G</td><td>implements</td><td>BIO-23</td><td>Interim protection is narrow and non-prejudicial.</td></tr><tr><td>CERGTA-26</td><td>Title, Tenure, Trust, Covenant, Licence, and Encumbrance Baseline Record</td><td>H</td><td>imports</td><td>BIO-22</td><td>Title, tenure, concessions, licences, and encumbrances remain under Hearthstone and applicable law.</td></tr><tr><td>CERGTA-27</td><td>Transfer, Rematriation, Trust Constitution, and Conveyance Authorization</td><td>H</td><td>imports</td><td>BIO-21, BIO-22</td><td>Biodiversity may support a transfer or rematriation claim but cannot authorize conveyance.</td></tr><tr><td>CERGTA-28</td><td>Compensation, Reparations, Debt, Tenant, Worker, User, and Service Continuity Record</td><td>H</td><td>imports</td><td>BIO-22, BIO-25, BIO-33, BIO-35</td><td>Compensation, debt, tenants, workers, users, and service continuity remain separate.</td></tr><tr><td>CERGTA-29</td><td>Commons, Title, Rights, Guardian, Permit, and Stewardship Registry Entry</td><td>H</td><td>extends</td><td>BIO-15, BIO-19, BIO-24, BIO-28, BIO-36</td><td>Biodiversity records may be registered only after their legal source is established.</td></tr><tr><td>CERGTA-30</td><td>Registry Error, Identity Collision, Boundary Conflict, and Correction Record</td><td>H</td><td>implements</td><td>BIO-36, BIO-46</td><td>Certification, identity, boundary, and registry errors require correction and propagation.</td></tr><tr><td>CERGTA-31</td><td>Stewardship Charter, Purpose, Powers, Duties, and Prohibited Acts</td><td>I</td><td>implements</td><td>BIO-24</td><td>Stewardship powers and prohibited acts are chartered.</td></tr><tr><td>CERGTA-32</td><td>Stewardship Plan, Ecological Objective, Budget, and Participation Record</td><td>I</td><td>implements</td><td>BIO-25</td><td>Plans include budgets, participation, livelihoods, welfare, review, and exit.</td></tr><tr><td>CERGTA-33</td><td>Stewardship Performance, Audit, Metric-Gaming, and Context Record</td><td>I</td><td>implements</td><td>BIO-26</td><td>Metrics trigger contextual review, not automatic sanction.</td></tr><tr><td>CERGTA-34</td><td>Stewardship Correction, Suspension, Revocation, Succession, and Dissolution Record</td><td>I</td><td>implements</td><td>BIO-27</td><td>Correction, capacity support, suspension, succession, and dissolution require due process.</td></tr><tr><td>CERGTA-35</td><td>Ecological Standard, Target, Plan, and Legal Adoption Status Record</td><td>J</td><td>implements</td><td>BIO-28</td><td>Targets and plans have explicit adoption states.</td></tr><tr><td>CERGTA-36</td><td>Resource Priority, Essential Minimum, Allocation Method, and Scarcity Record</td><td>K</td><td>extends</td><td>BIO-25, BIO-29</td><td>Resource priorities and essential minima are assessed through applicable sector frameworks.</td></tr><tr><td>CERGTA-37</td><td>Quota, Permit, Licence, Tariff, Bond, and Use-Condition Decision</td><td>K</td><td>imports</td><td>BIO-28, BIO-30, BIO-33, BIO-34, BIO-35</td><td>Quotas, permits, tariffs, bonds, and conditions require competent sector or financial authorities.</td></tr><tr><td>CERGTA-38</td><td>Commercial Restriction, Service Continuity, and Non-Deprivation Record</td><td>K</td><td>implements</td><td>BIO-37</td><td>Commercial restriction is distinct from scoring and certification.</td></tr><tr><td>CERGTA-39</td><td>Inspection Authorization, Entry, Sampling, and Report Record</td><td>L</td><td>implements</td><td>BIO-38</td><td>Inspection requires separate authority and scope.</td></tr><tr><td>CERGTA-40</td><td>Ecological Investigation Opening, Methods, Parties, and Closure Record</td><td>L</td><td>implements</td><td>BIO-39</td><td>Investigation is distinct from monitoring, advocacy, and inspection.</td></tr><tr><td>CERGTA-41</td><td>Ecological Evidence Custody, Scientific Attribution, and Admissibility Record</td><td>L</td><td>implements</td><td>BIO-40</td><td>Evidence and attribution preserve custody, uncertainty, and challenge.</td></tr><tr><td>CERGTA-42</td><td>Urgent Ecological Protection Authorization</td><td>M</td><td>implements</td><td>BIO-41</td><td>Urgency creates a request for narrow protection, not automatic closure or force.</td></tr><tr><td>CERGTA-43</td><td>Temporary Ecological Receivership and Administration Record</td><td>N</td><td>imports</td><td>BIO-41, BIO-42</td><td>Temporary receivership requires a competent authority; Biodiversity teams do not administer assets independently.</td></tr><tr><td>CERGTA-44</td><td>Port, Market, Procurement, Certification, Listing, and Delisting Restriction Record</td><td>N</td><td>implements</td><td>BIO-36, BIO-37</td><td>Certification and market restriction are separately authorized and corrected.</td></tr><tr><td>CERGTA-45</td><td>Ecological Tax, Tariff, Levy, Bond, Subsidy, and Funding Decision</td><td>O</td><td>implements</td><td>BIO-32, BIO-33, BIO-34, BIO-35</td><td>Payments, subsidies, bonds, and finance decisions remain distinct.</td></tr><tr><td>CERGTA-46</td><td>Freeze, Escrow, Forfeiture, Redistribution, Reparations, and Compensation Fund Record</td><td>O</td><td>imports</td><td>BIO-34, BIO-35, BIO-45, BIO-46</td><td>Freeze, escrow, forfeiture, redistribution, reparations, and compensation require competent financial or judicial authority.</td></tr><tr><td>CERGTA-47</td><td>Ecological and Commons Adjudication, Judgment, and Reasons Record</td><td>P</td><td>imports</td><td>BIO-43</td><td>Adjudication remains with an independent competent justice body.</td></tr><tr><td>CERGTA-48</td><td>Enforcement Request, Acceptance, Execution, and SCPA Interface Record</td><td>P</td><td>implements</td><td>BIO-43</td><td>Any coercive execution requires explicit acceptance and SCPA.</td></tr><tr><td>CERGTA-49</td><td>Ecological Restoration, Corrective Action, Requalification, and Verification Record</td><td>Q</td><td>implements</td><td>BIO-45</td><td>Restoration and requalification have independent verification and closure.</td></tr><tr><td>CERGTA-50</td><td>Appeal, Interim Relief, Complaint, Correction, Restitution, and Compensation Record</td><td>Q</td><td>implements</td><td>BIO-46</td><td>Appeal, interim relief, correction, restitution, and compensation are available.</td></tr><tr><td>CERGTA-51</td><td>Authority Expiry, Termination, Return, Succession, and Dissolution Record</td><td>R</td><td>implements</td><td>BIO-47</td><td>All programme and delegated authority has expiry, return, succession, and dissolution.</td></tr><tr><td>CERGTA-52</td><td>Data Return, Deletion, Archive, Public Memory, and Protected-Knowledge Disposition Record</td><td>R</td><td>implements</td><td>BIO-04, BIO-47</td><td>Data return, deletion, archive, and protected-knowledge disposition survive closure.</td></tr><tr><td>CERGTA-53</td><td>Unresolved Claim, Harm, Restoration, Service, and Duty Custody Record</td><td>R</td><td>implements</td><td>BIO-47</td><td>Unresolved claims and restoration duties remain visible without residual power.</td></tr><tr><td>CERGTA-54</td><td>Ecological and Commons Power Non-Activation, Pilot, and Sandbox Register</td><td>R</td><td>implements</td><td>BIO-48</td><td>Targets, pilots, coalition thresholds, and future dates never activate authority.</td></tr></tbody></table> <p>An unmapped applicable record is imported, not omitted. A combined case file may contain several records, but their legal effects remain separate.</p> <h2>23. Constitutional readiness gates</h2> <table><thead><tr><th>Gate</th><th>Title</th><th>Pass condition</th></tr></thead><tbody><tr><td>G01</td><td>Exact source and version pins</td><td>The source, CERGTA, EIOI, PHG, Indigenous, justice, emergency, and coercion interfaces are hash-pinned.</td></tr><tr><td>G02</td><td>Constituting law before authority</td><td>BCT, Hubs, fund bodies, guardians, inspectors, and programme offices act only under a valid BIO-01 record.</td></tr><tr><td>G03</td><td>No biodiversity sovereign</td><td>No BCT, PHC, Hub, dashboard, board, or coalition acquires general ecological jurisdiction by framework declaration.</td></tr><tr><td>G04</td><td>Observation–consequence separation</td><td>Citizen science, satellite data, scores, and thresholds cannot create rights, restrictions, payments, or penalties.</td></tr><tr><td>G05</td><td>Method transparency and uncertainty</td><td>Indicators, baselines, weights, uncertainty, dissent, sensitivity, and correction are public or appropriately protected.</td></tr><tr><td>G06</td><td>Affected-nation authority</td><td>Only the specific affected Indigenous nation may provide its consent, law, representatives, knowledge permissions, or non-engagement.</td></tr><tr><td>G07</td><td>Global representation not proxy consent</td><td>Indigenous seats or voting weights inside BCT govern BCT only; they do not grant FPIC for affected nations.</td></tr><tr><td>G08</td><td>Protected knowledge firewall</td><td>Traditional, sacred, genetic, and community knowledge retains access, purpose, benefit-sharing, correction, return, and deletion controls.</td></tr><tr><td>G09</td><td>Rights review separate from recognition</td><td>Biodiversity bodies may petition and recommend; a competent legal authority alone recognizes rights.</td></tr><tr><td>G10</td><td>No automatic rights escalation</td><td>A bleaching, decline, extinction-risk, or habitat-loss threshold triggers review or urgent-protection referral, not an automatic veto.</td></tr><tr><td>G11</td><td>Rights do not create title</td><td>Personhood and ecological rights do not transfer land, infrastructure, concessions, permits, or adjacent property.</td></tr><tr><td>G12</td><td>Guardian constitution</td><td>Nomination, appointment, fiduciary duty, conflicts, removal, liability, and succession are independently recorded.</td></tr><tr><td>G13</td><td>No guardian ownership or regulator role</td><td>A guardian represents the ecosystem but does not own it or automatically control permits, funds, inspections, or enforcement.</td></tr><tr><td>G14</td><td>BCT functional separation</td><td>Coordination, standards, fund administration, rights review, procurement, investigation, adjudication, and enforcement are separated.</td></tr><tr><td>G15</td><td>Hub delegation and local law</td><td>Regional Hubs have only host-jurisdiction powers expressly delegated and cannot self-enact stricter binding standards.</td></tr><tr><td>G16</td><td>Ethics board advisory status</td><td>The Ecological & Welfare Ethics Board records analysis and dissent but does not adjudicate rights or authorize intervention.</td></tr><tr><td>G17</td><td>Stewardship due process</td><td>Charters, plans, audits, correction, suspension, succession, and dissolution follow notice, context, support, review, and remedy.</td></tr><tr><td>G18</td><td>No score-to-payment automation</td><td>Verified activity does not itself determine UBES eligibility, amount, withholding, fraud, or repayment.</td></tr><tr><td>G19</td><td>No essential-service conditioning</td><td>Biodiversity payments, grants, certifications, or participation cannot condition essential water, food, housing, healthcare, sanitation, or legal protection.</td></tr><tr><td>G20</td><td>Subsidy transition before withdrawal</td><td>Harmful-subsidy reform identifies workers and communities and provides lawful budget process and just-transition support.</td></tr><tr><td>G21</td><td>Finance instruments bounded</td><td>Bonds, guarantees, debt swaps, grants, and credits cannot collateralize ecosystem personhood, extinguish claims, or self-enforce restrictions.</td></tr><tr><td>G22</td><td>Certification–market separation</td><td>A Bio-Credit or passport field cannot itself block a product, supplier, vessel, community, or nation from a market.</td></tr><tr><td>G23</td><td>Procurement and trade due process</td><td>Any restriction has lawful authority, individualized evidence, notice, review, expiry, correction, delisting, and essential-goods safeguards.</td></tr><tr><td>G24</td><td>Inspection–investigation separation</td><td>Monitoring, inspection, investigation, evidence custody, attribution, adjudication, and execution remain distinct.</td></tr><tr><td>G25</td><td>No predefined guilt or universal penalty</td><td>The framework does not predetermine ecocide jurisdiction, guilt, fines, officer liability, or remedy.</td></tr><tr><td>G26</td><td>Whistleblower support not allegation purchase</td><td>Protection and rewards are separated from evidence credibility, investigative cooperation, guilt, and outcome.</td></tr><tr><td>G27</td><td>Urgent protection fail-closed</td><td>Imminent harm may trigger a CERGTA-42 request; no automatic team deployment, fund release, closure, seizure, or force follows.</td></tr><tr><td>G28</td><td>Emergency command external</td><td>Biodiversity assistance teams operate under CDEE/ECRC and cannot create independent command, intelligence, custody, or force.</td></tr><tr><td>G29</td><td>SCPA execution boundary</td><td>Search, seizure, arrest, restraint, custody, force, cyber action, asset freezing, and border measures require separate SCPA authority.</td></tr><tr><td>G30</td><td>Adoption-state clarity</td><td>Advisory, voluntary, contractual, locally enacted, treaty-active, suspended, expired, and terminated states are explicit.</td></tr><tr><td>G31</td><td>Pilot and target non-activation</td><td>Percentages, future dates, personhood counts, coalition size, and pilot success do not activate authority.</td></tr><tr><td>G32</td><td>Closure and unresolved duties</td><td>Authority ends; data, claims, restoration, compensation, and correction duties remain without residual power.</td></tr></tbody></table> <h2>24. Compound implementation tests</h2> <table><thead><tr><th>Test</th><th>Scenario</th><th>Expected constitutional route</th></tr></thead><tbody><tr><td>T01</td><td>Citizen species count flags decline</td><td>BIO-03 records the observation; BIO-05/06 validate and interpret it; no rights, veto, payment, or sanction follows automatically.</td></tr><tr><td>T02</td><td>Coral bleaching crosses 20 percent</td><td>The threshold opens BIO-14 or BIO-41 review; it does not automatically suspend permits or create a reef veto.</td></tr><tr><td>T03</td><td>Local river seeks personhood</td><td>BIO-13/14 prepare review; a competent CERGTA-13 decision creates rights; BIO-17 and BIO-19 separately govern boundary and guardian.</td></tr><tr><td>T04</td><td>Personhood overlaps farms and homes</td><td>BIO-16/17 preserve non-derogable human, Indigenous, tenure, and service rights; personhood does not transfer property.</td></tr><tr><td>T05</td><td>Two Indigenous nations claim authority</td><td>BIO-08 and BIO-22 preserve both nations’ laws and claims; BCT voting weights cannot decide consent.</td></tr><tr><td>T06</td><td>Community refuses data sharing</td><td>BIO-04/08 honor non-engagement and protected knowledge; refusal cannot terminate support or create an adverse inference.</td></tr><tr><td>T07</td><td>Sacred species knowledge is submitted</td><td>Only the permitted public or protected layer is used; downstream systems cannot infer or disclose the restricted source.</td></tr><tr><td>T08</td><td>BCT has 40 percent Indigenous voting weight</td><td>The voting rule governs BCT’s own decisions only and cannot provide FPIC or override an affected nation.</td></tr><tr><td>T09</td><td>Regional Hub adopts stricter standard</td><td>BIO-11/28 require host-law authority or voluntary adoption; the Hub cannot make a binding rule by declaration.</td></tr><tr><td>T10</td><td>Rewilding threatens individual-animal welfare</td><td>BIO-12/29 records ecological necessity, welfare harm, alternatives, affected-nation input, dissent, and review; the Board does not adjudicate.</td></tr><tr><td>T11</td><td>Gene-drive proposal in a BAZ</td><td>BIO-30 may recommend research controls or moratorium review; any binding restriction requires competent CERGTA authority.</td></tr><tr><td>T12</td><td>Community restoration earns UBES</td><td>BIO-31 verifies activity; BIO-32 routes a separate AUBI decision with appeal and correction.</td></tr><tr><td>T13</td><td>Love Ledger record is duplicated</td><td>The ecological record is corrected before payment; duplication does not establish fraud or authorize clawback.</td></tr><tr><td>T14</td><td>Restoration score declines after wildfire</td><td>BIO-26 identifies the external shock; no automatic suspension, repayment, or steward replacement occurs.</td></tr><tr><td>T15</td><td>Steward persistently fails duties</td><td>BIO-26 precedes BIO-27, with support, notice, independent review, interim relief, succession, and remedy.</td></tr><tr><td>T16</td><td>Fossil-fuel subsidy is targeted for redirection</td><td>BIO-33 maps authority, beneficiaries, workers, communities, alternatives, transition support, budget process, and review.</td></tr><tr><td>T17</td><td>Impact bond finances habitat restoration</td><td>BIO-34 keeps investor return, ecological verification, community rights, public finance, and ecosystem non-collateralization separate.</td></tr><tr><td>T18</td><td>Debt-for-nature swap covers Indigenous territory</td><td>BIO-35 cannot waive Indigenous claims or transfer ecological title; BIO-08/22 and separate legal processes control.</td></tr><tr><td>T19</td><td>Negative Bio-Credit appears in product passport</td><td>BIO-36 records and corrects the claim; no market exclusion occurs without a separately lawful BIO-37/CERGTA-44 decision.</td></tr><tr><td>T20</td><td>Palm-oil supplier is proposed for exclusion</td><td>BIO-37 requires supply-chain evidence, notice, worker and food safeguards, proportionality, review, expiry, and delisting.</td></tr><tr><td>T21</td><td>Subsistence producer has poor digital records</td><td>Low-tech and community evidence remain valid; missing digital infrastructure does not create a negative score or exclusion.</td></tr><tr><td>T22</td><td>Whistleblower alleges illegal logging</td><td>BIO-44 protects the source; BIO-39 independently opens an investigation; reward eligibility does not prove the allegation.</td></tr><tr><td>T23</td><td>Satellite image suggests illegal extraction</td><td>BIO-03/06 support review; BIO-38/39 require separate authority before entry or investigation.</td></tr><tr><td>T24</td><td>Investigation finds mixed causal evidence</td><td>BIO-40 preserves alternatives and exculpatory material; adjudication cannot treat the model score as guilt.</td></tr><tr><td>T25</td><td>Ecocide case is referred</td><td>BIO-43 transfers a bounded package; the justice body independently determines jurisdiction, law, evidence, guilt, remedy, and appeal.</td></tr><tr><td>T26</td><td>Court orders restoration</td><td>BIO-45 records corrective duties and verification; physical execution or asset freezing requires CERGTA-48 and SCPA.</td></tr><tr><td>T27</td><td>Acute habitat destruction exceeds ten percent</td><td>BIO-41 requests urgent protection; no automatic team deployment or five-percent fund release occurs.</td></tr><tr><td>T28</td><td>Biodiversity assistance team deploys after cyclone</td><td>BIO-42 operates under CDEE/ECRC command and provides civilian technical assistance only.</td></tr><tr><td>T29</td><td>Protected-area plan displaces workers</td><td>BIO-07/25 require livelihoods, bargaining, retraining, compensation, food and service continuity before implementation.</td></tr><tr><td>T30</td><td>Protected-area designation overlaps customary use</td><td>BIO-21/22 preserve customary and occupancy evidence and require separate lawful designation and remedy.</td></tr><tr><td>T31</td><td>Pilot reaches personhood target</td><td>BIO-48 records the milestone but creates no authority to recognize another ecosystem or declare the pilot constitutionally successful.</td></tr><tr><td>T32</td><td>Twenty nations join the coalition</td><td>Coalition size does not itself make BCT decisions binding; each power remains separately enacted.</td></tr><tr><td>T33</td><td>BCT administers a biodiversity fund</td><td>BIO-10/34 separate programme governance, fund custody, grant decisions, procurement, audit, and appeals.</td></tr><tr><td>T34</td><td>Programme closes with open restoration duties</td><td>BIO-47 returns authority and preserves restoration, claims, data, correction, and compensation duties without residual command.</td></tr><tr><td>T35</td><td>Certification error causes market loss</td><td>BIO-36/46 correct the record, propagate correction, provide interim relief and compensation, and support delisting review.</td></tr><tr><td>T36</td><td>Enforcement request includes search and seizure</td><td>BIO-43 records the request; CERGTA-48 and SCPA independently govern acceptance, warrant, execution, custody, termination, and remedy.</td></tr></tbody></table> <h2>25. Versioning, adoption, and compatibility</h2> <p>A jurisdiction adopts v1.1 only through a controlled instrument identifying the exact version and hash, local authority, powers activated, powers withheld, implementing bodies, transition from v1.0, open cases, data migration, review date, and withdrawal path.</p> <p>A higher version number or similar title is not automatically compatible. Material changes to rights recognition, guardianship, Indigenous authority, finance, trade, investigation, emergency response, or enforcement require a new conformance review.</p> <h2>26. Transition from v1.0</h2> <p>The following v1.0 mechanisms are retired or reclassified:</p> <ul><li>BCT ecosystem-personhood ratification → rights-review support only;</li> <li>BCT control of UBES outcomes → separate activity verification and AUBI decision;</li> <li><code>20+ nations by 2040</code> binding authority → coalition instrument only where separately enacted;</li> <li>Regional Hub authority to adopt stricter binding standards → host-law or voluntary adoption only;</li> <li>Ecological & Welfare Ethics Board conflict resolution → advisory analysis only;</li> <li>automatic rights escalation and threshold veto → review or urgent-protection request;</li> <li>court-appointed guardians assumed by framework → competent CERGTA appointment;</li> <li>automatic Bio-Credit tariff rebate or surcharge → separate finance or trade decision;</li> <li>negative passport score causing market exclusion → separate CERGTA-44 route;</li> <li>predetermined ecocide penalties and officer liability → controlling law and independent adjudication;</li> <li>automatic Biodiversity SWAT Team deployment → civilian technical assistance under CDEE/ECRC;</li> <li>automatic five-percent emergency fund release → separate financial authorization;</li> <li>pilot, date, personhood-count, and coalition targets → non-activating programme metrics.</li></ul> <h2>27. Closing doctrine</h2> <blockquote><p><strong>The biosphere needs standing, restoration, and enforceable protection. Those aims are weakened—not strengthened—when observation, rights, money, trade, emergency response, and punishment are compressed into one institution.</strong></p></blockquote> <blockquote><p><strong>Biodiversity v1.1 therefore makes ecological action stronger by making every authority visible: affected peoples can know who decided, under what law, from which evidence, with what limits, until when, and how to challenge, correct, terminate, and repair it.</strong></p></blockquote> <hr> <h1>Controlled cluster-adoption appendix — CEACA/0.1</h1> <p><strong>Patch version:</strong> Global Governance Biodiversity Implementation Framework v1.1.1<br> <strong>Substantive base:</strong> Global Governance Biodiversity Implementation Framework v1.1<br> <strong>Cluster release:</strong> <code>CEA-CLUSTER/0.1</code><br> <strong>Adoption specification:</strong> <code>CEACA/0.1</code><br> <strong>Authority effect of this appendix:</strong> none; it establishes compatibility, inheritance, routing, and fail-closed rules only.</p> <h2>A.1 Exact compatibility set</h2> <p>This patch participates only in the following controlled document set. A renamed body, later version, compatible-sounding policy, or partial implementation does not silently enter the release. The machine-readable cluster registry freezes the SHA-256 digest of every file.</p> <table><thead><tr><th>Instrument</th><th>Exact compatible file</th><th>Cluster role</th></tr></thead><tbody><tr><td>CERGTA/0.1</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td>controlling authority interface</td></tr><tr><td>EIPHR/0.1</td><td><code>ecological-intelligence-planetary-health-role-separation-matrix-v0.1.md</code></td><td>EIOI–Planetary Health role separation</td></tr><tr><td>EIOI v2.7.1</td><td><code>ecological-intelligence-observation-interpretation-layer-v2.7.1.md</code></td><td>ecological observation, provenance, methods, uncertainty, interpretation, and advisory alerts</td></tr><tr><td>PHG v0.9.1</td><td><code>planetary-health-governance-framework-v0.9.1.md</code></td><td>independent synthesis, participatory audit, cross-domain coherence, and strategic recommendation</td></tr><tr><td>HEARTHSTONE v2.0.1</td><td><code>hearthstone-protocol-v2.0.1.md</code></td><td>voluntary conversion, claims support, title and tenure interfaces, trusts, rematriation, stewardship, and transition</td></tr><tr><td>WATER v5.2.2</td><td><code>water-sanitation-governance-framework-v5.2.2.md</code></td><td>watershed democracy, universal WASH, allocation, utilities, tariffs, guardianship interfaces, and emergency WASH</td></tr><tr><td>BIODIVERSITY v1.1.1</td><td><code>biodiversity-implementation-framework-v1.1.1.md</code></td><td>Indigenous-led stewardship support, restoration programmes, rights-review support, biodiversity finance interfaces, and accountability</td></tr><tr><td>OCEANS v2.3.1</td><td><code>oceans-marine-governance-framework-v2.3.1.md</code></td><td>marine stewardship, quotas and licensing interfaces, port-state measures, crew protection, precaution, and marine emergencies</td></tr><tr><td>SOIL v3.2.2</td><td><code>soil-health-land-use-governance-framework-v3.2.2.md</code></td><td>living-soil protection, regenerative land-use programmes, microbial commons, tenure interfaces, certification, and remediation</td></tr><tr><td>MOS v2.8.2</td><td><code>moral-operating-system-v2.8.2.md</code></td><td>advisory ethical deliberation, rights imagination, plural translation, and structural self-correction</td></tr></tbody></table> <h2>A.2 Controlling rules</h2> <ol><li><code>CERGTA/0.1</code> controls the separation of observation, interpretation, rights review, legal recognition, guardianship, affected Indigenous-nation authority, sacred and biocultural designation, claims, title, tenure, stewardship, allocation, permitting, inspection, urgent protection, restrictions, finance, adjudication, restoration, and closure.</li> <li><code>EIPHR/0.1</code> controls the division among EIOI, the Planetary Health Synthesis Office, and the Planetary Health Council. EIOI supplies evidence; PHSO compiles modular synthesis; PHC interprets and recommends. None may create a downstream legal or financial consequence.</li> <li>MOS is advisory only. Its Dynamic Rights Spectrum, philosophical language, developmental translations, structural-failure hypotheses, and guardianship metaphors never create legal status, classify persons, determine credibility, establish Indigenous consent, or activate consequential action.</li> <li>Hearthstone controls the cluster interface for claims, competing claims, title, tenure, trust constitution, voluntary conversion, rematriation, compensation, debt, tenants, workers, registry correction, receivership, succession, and dissolution. Sectoral ecological frameworks may provide evidence or programme support but cannot decide those questions by implication.</li> <li>Water, Biodiversity, Oceans, and Soil retain only the powers separately constituted in applicable law and recorded through the relevant CERGTA route. Framework membership, a council vote, a dashboard value, a target, a pilot, a future date, or a coalition size does not activate authority.</li> <li>Emergency identity and coordination use CDEE and ECRC. Ecological urgency does not create emergency command, and an emergency declaration does not create ecological title, guardianship, permanent restrictions, receivership, or enforcement authority.</li> <li>Search, seizure, restraint, custody, force, cyber action, border action, intelligence use, asset freezing, or analogous coercive execution requires separate SCPA authority. A commons or ecological claim may justify review; it does not authorize a raid.</li> <li>The specific affected Indigenous nation or nations determine their representatives, applicable law, territorial and relational authority, consent process, internal plurality, protected knowledge, and whether to participate. Global or framework-created Indigenous bodies may support or audit but cannot consent or waive rights for another people.</li> <li>Essential minimums for water, sanitation, health, disability support, food, shelter, rescue, crew welfare, and ecological survival remain protected from commercial, tariff, certification, funding, listing, or transition leverage.</li> <li>Every handoff uses the canonical CERGTA states. Receipt, technical ingestion, silence, consultation, or partial use is not acceptance and never creates authority.</li> <li>Every consequential route keeps its own legal basis, decision-maker, affected persons, evidence, access controls, clock, expiry, challenge, correction, remedy, termination, and data-disposition record.</li> <li>Unknown, missing, stale, or incompatible versions fail closed for consequential action. Non-coercive care, emergency life-safety support, accessibility, explanation, and correction should continue wherever lawful and safe.</li></ol> <h2>A.3 Record inheritance and packaging</h2> <p>A local record may implement, extend, split, contain, import, or mark a CERGTA record not applicable. It may not erase the canonical identity, merge distinct powers, weaken an affected-person safeguard, or use a compound package to supply a missing legal basis.</p> <p>The forty-field CERGTA header, access classification, handoff state, independent clocks, correction propagation, remedy, termination, authority return, and data disposition are inherited wherever the substantive base creates or transports a consequential record. Advisory and observation-only records must state their prohibited inferences.</p> <h2>A.4 Registry and compatibility failure</h2> <p>The file <code>commons-ecological-authority-cluster-conformance-registry-v0.1.json</code> is the machine-readable release registry. It is evidence of the exact release set, not an authority record. A hash mismatch, missing component, unsupported local extension, or unresolved version conflict changes the compatibility state to <code>failed_closed</code>.</p> <p>A compatibility failure blocks new consequential cross-framework handoffs. It does not by itself terminate independently valid local law, erase existing rights, interrupt essential services, or authorize emergency or coercive action.</p> <h2>A.5 Closure</h2> <p>A cluster transaction closes only after all accepted handoffs, powers, services, persons, property, guardianship duties, claims, title or tenure effects, financial actions, emergency dependencies, coercive dependencies, corrections, remedies, clocks, credentials, records, and residual risks are resolved or assigned to a named lawful custodian without preserving expired power.</p> <h2>A.6 Editorial patch note</h2> <p>This patch is <strong>editorial only</strong>. No doctrine, power, boundary, record, gate, or test was added, removed, or weakened.</p> <p>Changes:</p> <ol><li><strong>§1 source freeze.</strong> Clarified as a provenance record rather than an operative dependency set, resolving an ambiguity against Appendix A.1.</li> <li><strong>A.1 compatibility set.</strong> Updated to name the current editions of Water, Soil, and the Moral Operating System, which were editorially revised after this release. The change is editorial in each case, so the correct response is to update the pin rather than treat the mismatch as a substantive conflict.</li></ol> <p>This document required no other change. Its record catalogue was already tabular and its crosswalk carries distinct content in every row.</p>",1);function c(t){var e=o();n(472),r(t,e)}export{c as default};
